// Tariro_ide_idpte/src/cognitive_arch/imagination_models.rs

//! Defines data models for Tariro's Imagination & Counterfactual Thinking module,
//! including representations of imagined scenarios and counterfactual states.

use serde::{Serialize, Deserialize};
use chrono::{Utc, DateTime};
use std::collections::HashMap;

use crate::cognitive_arch::learning_models::VerificationStatus; // For verification statuses

/// Represents a simulated scenario or possible future state generated by Tariro.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ImaginedScenario {
    pub id: String,
    pub description: String,
    pub base_state_id: String, // Link to the real state it diverged from
    pub divergent_features: HashMap<String, String>, // What makes this scenario different
    pub predicted_outcomes: Vec<String>,
    pub probability_score: f64, // Estimated likelihood (0.0 to 1.0)
    pub relevance_to_goals: Vec<String>, // IDs of goals this scenario informs
    pub verification_status: ScenarioVerificationStatus, // New: Ethical/Security review status
    pub created_at: DateTime<Utc>,
}

/// Represents a counterfactual state - a specific "what-if" modification of a real state.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CounterfactualState {
    pub id: String,
    pub real_state_snapshot_id: String,
    pub modification_summary: String, // e.g., "If intervention X had occurred"
    pub inferred_impacts: HashMap<String, f64>, // Predicted changes in variables
    pub causal_chain_summary: String, // Rationale based on CausalReasoningEngine
    pub ethical_implications_summary: String, // Rationale based on ALEC-A
    pub timestamp: DateTime<Utc>,
}

/// Comprehensive verification status for an imagined scenario.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ScenarioVerificationStatus {
    pub ethical_safety_status: VerificationStatus, // Ensuring imagined actions are ethically safe
    pub security_simulation_status: VerificationStatus, // Ensuring scenario doesn't expose system vulnerabilities
    pub logical_plausibility_status: VerificationStatus, // Consistent with common sense and causal laws
    pub overall_status: VerificationStatus,
    pub last_verified: DateTime<Utc>,
    pub verification_log_id: String,
}
